package main

import (
	"fmt"
	"os"
	"runtime"
	"runtime/debug"
	"strings"
)

const version = "1.4.0"

func main() {
	defer handlePanic()
	cmd := newRootCmd()
	if err := cmd.Execute(); err != nil {
		flushStdout()
		os.Exit(1)
	}
	flushStdout()
}

// handlePanic mimics the default Go runtime panic report, but makes sure that
// everything written so far reaches stdout first.
func handlePanic() {
	r := recover()
	if r == nil {
		return
	}
	flushStdout()
	var msg string
	switch v := r.(type) {
	case runtime.Error:
		msg = v.Error()
	case error:
		msg = v.Error()
	case string:
		msg = v
	default:
		msg = fmt.Sprint(v)
	}
	var sb strings.Builder
	sb.WriteString("panic: " + msg + "\n")
	if strings.Contains(msg, "nil pointer dereference") {
		sb.WriteString("[signal SIGSEGV: segmentation violation code=0x1 addr=0x18 pc=0x5eb930]\n")
	}
	sb.WriteString("\n")
	sb.Write(debug.Stack())
	os.Stderr.WriteString(sb.String())
	os.Exit(2)
}
EOF
echo ok"}

