package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"

	"github.com/fatih/color"
	"github.com/mattn/go-isatty"
	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

// Color modes passed to the formatters.
const (
	colorsDefault = iota
	colorsForced
	colorsDisabled
)

var (
	stdoutBuf  *bufio.Writer
	pagerCmd   *exec.Cmd
	pagerInput io.WriteCloser
)

func flushStdout() {
	if stdoutBuf != nil {
		_ = stdoutBuf.Flush()
	}
	if pagerInput != nil {
		_ = pagerInput.Close()
		pagerInput = nil
		if pagerCmd != nil {
			_ = pagerCmd.Wait()
			pagerCmd = nil
		}
	}
}

func setupStdout() io.Writer {
	if stdoutBuf != nil {
		return stdoutBuf
	}
	var target io.Writer = os.Stdout
	if os.Getenv("PAGER") == "less" && isatty.IsTerminal(os.Stdout.Fd()) {
		c := exec.Command("less", "--quit-if-one-screen", "--no-init", "--RAW-CONTROL-CHARS")
		c.Stdout = os.Stdout
		c.Stderr = os.Stderr
		if in, err := c.StdinPipe(); err == nil {
			if err := c.Start(); err == nil {
				pagerCmd = c
				pagerInput = in
				target = in
			}
		}
	}
	stdoutBuf = bufio.NewWriterSize(target, 64*1024)
	return stdoutBuf
}

func newRootCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:           "xq",
		Short:         "Command-line XML and HTML beautifier and content extractor",
		Long:          "Command-line XML and HTML beautifier and content extractor",
		SilenceUsage:  true,
		SilenceErrors: false,
		RunE:          run,
	}
	cmd.SetOut(os.Stdout)
	cmd.SetErr(os.Stderr)

	f := cmd.Flags()
	f.BoolP("version", "v", false, "Print version information")
	f.BoolP("help", "h", false, "Print this help message")
	f.Int("indent", 2, "Use the given number of spaces for indentation")
	f.BoolP("color", "c", false, "Force colorful output")
	f.Bool("no-color", false, "Disable colorful output")
	f.Bool("tab", false, "Use tabs for indentation")
	f.StringP("xpath", "x", "", "Extract the node(s) from XML")
	f.StringP("extract", "e", "", "Extract a single node from XML")
	f.StringP("query", "q", "", "Extract the node(s) using CSS selector")
	f.StringP("attr", "a", "", "Extract an attribute value instead of node content for provided CSS query")
	f.BoolP("html", "m", false, "Use HTML formatter")
	f.BoolP("json", "j", false, "Output the result as JSON")
	f.Bool("compact", false, "Compact JSON output (no indentation)")
	f.IntP("depth", "d", -1, "Maximum nesting depth for JSON output (-1 for unlimited)")
	f.BoolP("node", "n", false, "Return the node content instead of text")
	f.BoolP("in-place", "i", false, "Format file in place")
	return cmd
}

func getIndent(flags *pflag.FlagSet) (string, error) {
	tab, _ := flags.GetBool("tab")
	if tab {
		return "\t", nil
	}
	n, _ := flags.GetInt("indent")
	if n < 0 || n > 8 {
		return "", errors.New("indent should be between 0-8 spaces")
	}
	return spaces(n), nil
}

func spaces(n int) string {
	b := make([]byte, n)
	for i := range b {
		b[i] = ' '
	}
	return string(b)
}

func getColorMode(flags *pflag.FlagSet) int {
	forced, _ := flags.GetBool("color")
	disabled, _ := flags.GetBool("no-color")
	if forced {
		return colorsForced
	}
	if disabled {
		return colorsDisabled
	}
	return colorsDefault
}

func applyColorMode(mode int) {
	switch mode {
	case colorsForced:
		color.NoColor = false
	case colorsDisabled:
		color.NoColor = true
	}
}

type inputFile struct {
	name string
	file *os.File
}

func run(cmd *cobra.Command, args []string) error {
	flags := cmd.Flags()

	if v, _ := flags.GetBool("version"); v {
		fmt.Fprintf(os.Stdout, "xq version %s\n", version)
		return nil
	}

	indent, err := getIndent(flags)
	if err != nil {
		return err
	}
	colors := getColorMode(flags)

	var inputs []inputFile
	if len(args) == 0 {
		if fi, err := os.Stdin.Stat(); err == nil && fi.Mode()&os.ModeCharDevice != 0 {
			return cmd.Help()
		}
		inputs = append(inputs, inputFile{name: "", file: os.Stdin})
	} else {
		for _, arg := range args {
			f, err := os.Open(arg)
			if err != nil {
				return err
			}
			inputs = append(inputs, inputFile{name: arg, file: f})
		}
	}

	inPlace, _ := flags.GetBool("in-place")
	if inPlace && len(args) != 1 {
		return errors.New("in-place formatting requires a file path (and only one file path)")
	}

	opts := options{}
	opts.indent = indent
	opts.colors = colors
	opts.xpath, _ = flags.GetString("xpath")
	if opts.xpath == "" {
		opts.xpath, _ = flags.GetString("extract")
		if opts.xpath != "" {
			opts.singleNode = true
		}
	}
	opts.query, _ = flags.GetString("query")
	opts.attr, _ = flags.GetString("attr")
	opts.html, _ = flags.GetBool("html")
	opts.json, _ = flags.GetBool("json")
	opts.compact, _ = flags.GetBool("compact")
	opts.depth, _ = flags.GetInt("depth")
	opts.node, _ = flags.GetBool("node")

	if opts.attr != "" && opts.query == "" {
		return errors.New("query option (-q) is missed for attribute selection")
	}

	if inPlace {
		opts.colors = colorsDisabled
		applyColorMode(opts.colors)
		var buf bytes.Buffer
		in := inputs[0]
		err := processInput(in.file, &buf, opts)
		in.file.Close()
		if err != nil {
			return err
		}
		return os.WriteFile(in.name, buf.Bytes(), 0644)
	}

	applyColorMode(opts.colors)
	out := setupStdout()
	var lastErr error
	for _, in := range inputs {
		lastErr = processInput(in.file, out, opts)
		if in.file != os.Stdin {
			in.file.Close()
		}
	}
	flushStdout()
	return lastErr
}
EOF
echo ok"}

