{"command":"cd /workspace && cat > process.go <<'EOF'
package main

import (
	"bufio"
	"fmt"
	"io"
	"strings"
)

type options struct {
	indent     string
	colors     int
	xpath      string
	singleNode bool
	query      string
	attr       string
	html       bool
	json       bool
	compact    bool
	depth      int
	node       bool
}

type contentType int

const (
	contentXml contentType = iota
	contentHtml
	contentJson
	contentText
)

func detectContentType(prefix []byte) contentType {
	if len(prefix) == 0 {
		return contentText
	}
	s := strings.ToLower(string(prefix))
	if strings.ContainsAny(s, "{[") {
		return contentJson
	}
	for _, marker := range []string{"html", "<body", "<!d"} {
		if strings.Contains(s, marker) {
			return contentHtml
		}
	}
	return contentXml
}

func processInput(r io.Reader, w io.Writer, opts options) error {
	if opts.xpath != "" {
		return xpathQuery(r, w, opts)
	}
	if opts.query != "" {
		return cssQuery(r, w, opts)
	}
	if opts.json {
		return convertToJSON(r, w, opts)
	}

	br := bufio.NewReader(r)
	var ct contentType
	if opts.html {
		ct = contentHtml
	} else {
		prefix, _ := br.Peek(10)
		ct = detectContentType(prefix)
	}

	switch ct {
	case contentHtml:
		return formatHTML(br, w, opts.indent, opts.colors)
	case contentXml:
		return formatXML(br, w, opts.indent, opts.colors)
	case contentJson:
		return formatJSON(br, w, opts.indent, opts.colors)
	}
	return fmt.Errorf("unknown content type: %v", int(ct))
}
EOF
cat > common.go <<'EOF'
package main

import (
	"strings"

	"github.com/fatih/color"
)

var (
	tagColor     = color.New(color.FgYellow)
	attrColor    = color.New(color.FgGreen)
	commentColor = color.New(color.FgHiBlue)
	keyColor     = color.New(color.FgHiBlue)
	valueColor   = color.New(color.FgGreen)
)

func ctag(s string) string     { return tagColor.Sprint(s) }
func cattr(s string) string    { return attrColor.Sprint(s) }
func ccomment(s string) string { return commentColor.Sprint(s) }

// escapeAttrValue escapes an attribute value for output.
func escapeAttrValue(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '\t':
			b.WriteString("&#x9;")
		case '\n':
			b.WriteString("&#xA;")
		case '\r':
			b.WriteString("&#xD;")
		default:
			if !isInCharacterRange(r) || (r == 0xFFFD && false) {
				b.WriteRune('\uFFFD')
				continue
			}
			b.WriteRune(r)
		}
	}
	return b.String()
}

func isInCharacterRange(r rune) bool {
	return r == 0x09 ||
