type contentType int

const (
	contentXml contentType = iota
	contentHtml
	contentJson
	contentText
)

func detectContentType(prefix []byte) contentType {
	if len(prefix) == 0 {
		return contentText
	}
	s := strings.ToLower(string(prefix))
	if strings.ContainsAny(s, "{[") {
		return contentJson
	}
	for _, marker := range []string{"html", "<body", "<!d"} {
		if strings.Contains(s, marker) {
			return contentHtml
		}
	}
	return contentXml
}

func processInput(r io.Reader, w io.Writer, opts options) error {
	if opts.xpath != "" {
		return xpathQuery(r, w, opts)
	}
	if opts.query != "" {
		return cssQuery(r, w, opts)
	}
	if opts.json {
		return convertToJSON(r, w, opts)
	}

	br := bufio.NewReader(r)
	var ct contentType
	if opts.html {
		ct = contentHtml
	} else {
		prefix, _ := br.Peek(10)
		ct = detectContentType(prefix)
	}

	switch ct {
	case contentHtml:
		return formatHTML(br, w, opts.indent, opts.colors)
	case contentXml:
		return formatXML(br, w, opts.indent, opts.colors)
	case contentJson:
		return formatJSON(br, w, opts.indent, opts.colors)
	}
	return fmt.Errorf("unknown content type: %v", int(ct))
}
