	"golang.org/x/text/encoding/ianaindex"
	"golang.org/x/text/encoding/unicode"
)

const xmlNamespaceURL = "http://www.w3.org/XML/1998/namespace"

func getCharsetReader(label string, input io.Reader) (io.Reader, error) {
	if strings.ToLower(label) == "utf-16" {
		return unicode.UTF8.NewDecoder().Reader(input), nil
	}
	enc, err := ianaindex.IANA.Encoding(label)
	if err != nil {
		return nil, err
	}
	// A nil encoding (registered but unsupported) leads to a nil pointer
	// dereference, just like the original implementation.
	return enc.NewDecoder().Reader(input), nil
}

type nsAliasMap map[string]string

func (m nsAliasMap) fullName(name xml.Name) string {
	if name.Space == "" {
		return name.Local
	}
	if alias, ok := m[name.Space]; ok {
		if alias == "" {
			return name.Local
		}
		return alias + ":" + name.Local
	}
	return name.Space + ":" + name.Local
}

func formatXML(r io.Reader, w io.Writer, indent string, colors int) error {
	decoder := xml.NewDecoder(r)
	decoder.Strict = false
	decoder.CharsetReader = getCharsetReader

	level := 0
	hasContent := false
	nsAliases := nsAliasMap{xmlNamespaceURL: "xml"}
	lastTagName := ""
	startTagClosed := true
	newline := "\n"
	if indent == "" {
		newline = ""
	}

	write := func(parts ...string) {
		for _, p := range parts {
			io.WriteString(w, p)
		}
	}

	for {
		token, err := decoder.Token()
		if err != nil {
			if err == io.EOF {
				write("\n")
				return nil
			}
			return err
		}

		switch t := token.(type) {
		case xml.ProcInst:
			write(ctag("<?"), t.Target)
			inst := strings.TrimSpace(string(t.Inst))
			for _, part := range strings.Split(inst, " ") {
				kv := strings.SplitN(part, "=", 2)
				write(" ", kv[0], cattr("="+kv[1]))
			}
			write(ctag("?>"), newline)

		case xml.StartElement:
			if !startTagClosed {
				write(ctag(">"))
				startTagClosed = true
			}
			if level > 0 {
				write(newline, strings.Repeat(indent, level))
			}
			var attrs strings.Builder
			for _, attr := range t.Attr {
				if attr.Name.Space == "xmlns" {
					if nsAliases[attr.Value] == "" {
						nsAliases[attr.Value] = attr.Name.Local
					}
				} else if attr.Name.Space == "" && attr.Name.Local == "xmlns" {
					nsAliases[attr.Value] = ""
				}
				attrs.WriteString(" ")
				attrs.WriteString(nsAliases.fullName(attr.Name))
				attrs.WriteString(cattr("=\"" + escapeAttrValue(attr.Value) + "\""))
			}
			name := nsAliases.fullName(t.Name)
			write(ctag("<"+name), attrs.String())
			lastTagName = name
			startTagClosed = false
			hasContent = false
			level++

		case xml.CharData:
			str := normalizeSpaces(string(t), indent, level)
			hasContent = str != ""
			if hasContent && !startTagClosed {
				write(ctag(">"))
				startTagClosed = true
			}
			if strings.ContainsAny(str, "<&") {
				write("<![CDATA[", str, "]]>")
			} else {
				write(str)
			}

		case xml.Comment:
			if !startTagClosed {
				write(ctag(">"))
				startTagClosed = true
			}
			sep := ""
			if level > 0 && !hasContent {
				sep = newline + strings.Repeat(indent, level)
				write(sep)
			}
			lines := strings.Split(string(t), "\n")
			write(ccomment("<!--"))
			for i, line := range lines {
				if i > 0 {
					write(sep)
				}
				write(ccomment(line))
			}
			write(ccomment("-->"))
			if level == 0 {
				write(newline)
			}

		case xml.Directive:
			write(ctag("<!"), string(t), ctag(">"), newline, strings.Repeat(indent, level))

		case xml.EndElement:
			level--
			name := nsAliases.fullName(t.Name)
			if !hasContent {
				if lastTagName != name {
					if !startTagClosed {
						write(ctag(">"))
						startTagClosed = true
					}
					write(newline, strings.Repeat(indent, level), ctag("</"+name+">"))
				} else {
					write(ctag("/>"))
					startTagClosed = true
				}
			} else {
				write(ctag("</" + name + ">"))
			}
			hasContent = false
			lastTagName = name
		}
	}
}
