package main

import (
	"encoding/json"
	"io"
	"strconv"
	"strings"
)

func formatJSON(r io.Reader, w io.Writer, indent string, colors int) error {
	decoder := json.NewDecoder(r)
	decoder.UseNumber()

	newline := "\n"
	if indent == "" {
		newline = ""
	}
	write := func(parts ...string) {
		for _, p := range parts {
			io.WriteString(w, p)
		}
	}
	prefixFor := func(level int) string {
		if level < 1 {
			level = 1
		}
		return strings.Repeat(indent, level)
	}

	level := 0
	prefix := ""
	commaFlag := false
	pending := false
	afterKey := false
	expectKey := false
	var stack []json.Delim

	separator := func() {
		if pending && commaFlag {
			write(",", newline)
			prefix = prefixFor(level)
		}
		pending = false
		if afterKey {
			write(": ")
			afterKey = false
		}
	}

	for {
		token, err := decoder.Token()
		if err != nil {
			if err == io.EOF {
				write("\n")
				return nil
			}
			return err
		}

		switch v := token.(type) {
		case json.Delim:
			switch v {
			case '{', '[':
				separator()
				write(prefix, ctag(v.String()), newline)
				level++
				prefix = strings.Repeat(indent, level)
				commaFlag = false
				stack = append(stack, v)
				expectKey = v == '{'
			case '}', ']':
				afterKey = false
				level--
				write(newline, strings.Repeat(indent, max(level, 0)), ctag(v.String()))
				prefix = prefixFor(level)
				if len(stack) > 0 {
					stack = stack[:len(stack)-1]
				}
				if level >= 1 {
					commaFlag = true
				}
				pending = true
				expectKey = len(stack) > 0 && stack[len(stack)-1] == '{'
			}
		default:
			if s, ok := v.(string); ok && expectKey && len(stack) > 0 && stack[len(stack)-1] == '{' {
				separator()
				write(prefix, keyColor.Sprint(strconv.Quote(s)))
				prefix = ""
				afterKey = true
				expectKey = false
				continue
			}
			separator()
			var str string
			switch val := v.(type) {
			case string:
				str = strconv.Quote(val)
			case json.Number:
				str = val.String()
			case bool:
				if val {
					str = "true"
				} else {
					str = "false"
				}
			case nil:
				str = "null"
			}
			write(prefix, valueColor.Sprint(str))
			if level >= 1 {
				commaFlag = true
			}
			pending = true
			if len(stack) > 0 && stack[len(stack)-1] == '{' {
				expectKey = true
			}
		}
	}
}
EOF
