package main

import (
	"bytes"
	"encoding/xml"
	"errors"
	"fmt"
	"html"
	"io"
	"strings"

	"golang.org/x/net/html/charset"
)

// XML document model used by the XPath and JSON features.

type NodeType uint

const (
	DocumentNode NodeType = iota
	DeclarationNode
	ElementNode
	TextNode
	CharDataNode
	CommentNode
	AttributeNode
	NotationNode
	ProcessingInstructionNode
)

type Attr struct {
	Name         xml.Name // Space holds the prefix
	Value        string
	NamespaceURI string
}

type Node struct {
	Parent, FirstChild, LastChild, PrevSibling, NextSibling *Node

	Type         NodeType
	Data         string
	Prefix       string
	NamespaceURI string
	Attr         []Attr
	Inst         string

	level int
}

func addChild(parent, n *Node) {
	n.Parent = parent
	n.NextSibling = nil
	if parent.FirstChild == nil {
		parent.FirstChild = n
		n.PrevSibling = nil
	} else {
		parent.LastChild.NextSibling = n
		n.PrevSibling = parent.LastChild
	}
	parent.LastChild = n
}

func addSibling(sibling, n *Node) {
	for t := sibling.NextSibling; t != nil; t = t.NextSibling {
		sibling = t
	}
	n.Parent = sibling.Parent
	sibling.NextSibling = n
	n.PrevSibling = sibling
	n.level = sibling.level
	if sibling.Parent != nil {
