type node interface {
	Type() nodeType
}

type nodeBase struct{ typ nodeType }

func (n nodeBase) Type() nodeType { return n.typ }

type rootNode struct {
	nodeBase
	slash string
}

type axisNode struct {
	nodeBase
	Input     node
	Prop      string // node-test name: comment|text|processing-instruction|node
	AxeType   string
	LocalName string
	Prefix    string
}

type operandNode struct {
	nodeBase
	Val interface{}
}

type operatorNode struct {
	nodeBase
	Op          string
	Left, Right node
}

type filterNode struct {
	nodeBase
	Input, Condition node
}

type variableNode struct {
	nodeBase
	Name, Prefix string
}

type functionNode struct {
	nodeBase
	Args     []node
	Prefix   string
	FuncName string
}

type groupNode struct {
	nodeBase
	Input node
}

func newAxisNode(axeTyp, localName, prefix, prop string, n node) node {
	return &axisNode{
		nodeBase:  nodeBase{typ: nodeAxis},
		LocalName: localName,
		Prefix:    prefix,
		AxeType:   axeTyp,
		Prop:      prop,
		Input:     n,
	}
}

func newOperatorNode(op string, left, right node) node {
	return &operatorNode{nodeBase: nodeBase{typ: nodeOperator}, Op: op, Left: left, Right: right}
}

func newOperandNode(v interface{}) node {
	return &operandNode{nodeBase: nodeBase{typ: nodeConstantOperand}, Val: v}
}

func newFilterNode(n, m node) node {
	return &filterNode{nodeBase: nodeBase{typ: nodeFilter}, Input: n, Condition: m}
}

func newRootNode(s string) node {
	return &rootNode{nodeBase: nodeBase{typ: nodeRoot}, slash: s}
}

func newFunctionNode(name, prefix string, args []node) node {
	return &functionNode{nodeBase: nodeBase{typ: nodeFunction}, Prefix: prefix, FuncName: name, Args: args}
}

func newVariableNode(prefix, name string) node {
	return &variableNode{nodeBase: nodeBase{typ: nodeVariable}, Name: name, Prefix: prefix}
}

func newGroupNode(n node) node {
	return &groupNode{nodeBase: nodeBase{typ: nodeGroup}, Input: n}
}

type parser struct {
	r *scanner
	d int
}

func testOp(r *scanner, op string) bool {
	return r.typ == itemName && r.prefix == "" && r.name == op
}

func isPrimaryExpr(r *scanner) bool {
	switch r.typ {
	case itemString, itemNumber, itemDollar, itemLParens:
		return true
	case itemName:
		return r.canBeFunc && !isNodeType(r)
	}
	return false
}

func isNodeType(r *scanner) bool {
	switch r.name {
	case "node", "text", "processing-instruction", "comment":
		return r.prefix == ""
	}
	return false
}

func isStep(item itemType) bool {
	switch item {
	case itemDot, itemDotDot, itemAt, itemAxe, itemStar, itemName:
		return true
	}
	return false
}

func checkItem(r *scanner, typ itemType) {
	if r.typ != typ {
		panic(fmt.Sprintf("%s has an invalid token", r.text))
	}
}

func (p *parser) next() bool {
	return p.r.nextItem()
}

func (p *parser) skipItem(typ itemType) {
	if p.r.typ != typ {
		panic(fmt.Sprintf("%s expect %s but got %s", p.r.text, typ, p.r.typ))
	}
	p.next()
}

func (p *parser) parseExpression(n node) node {
	if p.d = p.d + 1; p.d > 200 {
		panic("the xpath query is too complex(depth > 200)")
	}
	n = p.parseOrExpr(n)
	p.d--
	return n
