package xpath

// NodeType represents a type of XPath node.
type NodeType int

const (
	// RootNode is a root node of the XML document or node tree.
	RootNode NodeType = iota
	// ElementNode is an element, such as <element>.
	ElementNode
	// AttributeNode is an attribute, such as id='123'.
	AttributeNode
	// TextNode is the text content of a node.
	TextNode
	// CommentNode is a comment node, such as <!-- my comment -->
	CommentNode
	// allNode is any types of node, used by xpath package only to predicate match.
	allNode
)

// NodeNavigator provides cursor model for navigating XML data.
type NodeNavigator interface {
	NodeType() NodeType
	LocalName() string
	Prefix() string
	Value() string
	Copy() NodeNavigator
	MoveToRoot()
	MoveToParent() bool
	MoveToNextAttribute() bool
	MoveToChild() bool
	MoveToFirst() bool
	MoveToNext() bool
	MovePrevious() bool
	MoveTo(NodeNavigator) bool
	// Key returns a value identifying the current position.
	Key() interface{}
}

type iterator interface {
	Current() NodeNavigator
}

type iteratorFunc func() NodeNavigator

func (f iteratorFunc) Current() NodeNavigator { return f() }

// NodeIterator holds all matched Node object.
type NodeIterator struct {
	node  NodeNavigator
	query query
}

// Current returns current node which matched.
func (t *NodeIterator) Current() NodeNavigator {
	return t.node
}

// MoveNext moves Navigator to the next match node.
func (t *NodeIterator) MoveNext() bool {
	n := t.query.Select(t)
	if n == nil {
		return false
	}
	if !t.node.MoveTo(n) {
		t.node = n.Copy()
	}
	return true
}

// Expr is an XPath expression for query.
type Expr struct {
	s string
	q query
}

// Evaluate returns the result of the expression.
// The result type of the expression is one of the follow: bool,float64,string,NodeIterator).
func (expr *Expr) Evaluate(root NodeNavigator) interface{} {
	val := expr.q.Evaluate(iteratorFunc(func() NodeNavigator { return root }))
	switch val.(type) {
	case query:
		return &NodeIterator{query: expr.q.Clone(), node: root}
	}
	return val
}

// Select selects a node set using the specified XPath expression.
func (expr *Expr) Select(root NodeNavigator) *NodeIterator {
	return &NodeIterator{query: expr.q.Clone(), node: root}
}

// Compile compiles an XPath expression string.
func Compile(expr string) (*Expr, error) {
	if expr == "" {
		return nil, errorString("expr expression is nil")
	}
	qy, err := build(expr)
	if err != nil {
		return nil, err
	}
	if qy == nil {
		return nil, errorString("undeclared variable in XPath expression: " + expr)
	}
	return &Expr{s: expr, q: qy}, nil
}

type errorString string

func (e errorString) Error() string { return string(e) }
EOF
