// Compile compiles an XPath expression string.
func Compile(expr string) (*Expr, error) {
	if expr == "" {
		return nil, errorString("expr expression is nil")
	}
	qy, err := build(expr)
	if err != nil {
		return nil, err
	}
	if qy == nil {
		return nil, errorString("undeclared variable in XPath expression: " + expr)
	}
	return &Expr{s: expr, q: qy}, nil
