func cmpBooleanBoolean(t iterator, op string, m, n interface{}) bool {
	a := m.(bool)
	b := n.(bool)
	return cmpBooleanBooleanF(op, a, b)
}

func getValueType(i interface{}) int {
	v := reflect.ValueOf(i)
	switch v.Kind() {
	case reflect.Float64:
		return 1
	case reflect.String:
		return 2
	case reflect.Bool:
		return 0
	default:
		if _, ok := i.(query); ok {
			return 3
		}
	}
	panic(fmt.Errorf("xpath unknown value type: %v", v.Kind()))
}

func cmpFunc(op string) func(iterator, interface{}, interface{}) interface{} {
	return func(t iterator, m, n interface{}) interface{} {
		t1 := getValueType(m)
		t2 := getValueType(n)
		return logicalFuncs[t1][t2](t, op, m, n)
	}
}

var (
	eqFunc = cmpFunc("=")
	gtFunc = cmpFunc(">")
	geFunc = cmpFunc(">=")
	ltFunc = cmpFunc("<")
	leFunc = cmpFunc("<=")
	neFunc = cmpFunc("!=")
)

func plusFunc(t iterator, m, n interface{}) interface{} {
