}

func minusFunc(t iterator, m, n interface{}) interface{} {
	return asNumber(t, m) - asNumber(t, n)
}

func mulFunc(t iterator, m, n interface{}) interface{} {
	return asNumber(t, m) * asNumber(t, n)
}

func divFunc(t iterator, m, n interface{}) interface{} {
	return asNumber(t, m) / asNumber(t, n)
}

func modFunc(t iterator, m, n interface{}) interface{} {
	a := asNumber(t, m)
	b := asNumber(t, n)
	return float64(int(a) % int(b))
}
