	last, ofType bool
}

func (s nthPseudoClassSelector) Match(n *html.Node) bool {
	if s.a == 0 {
		if s.last {
			return simpleNthLastChildMatch(s.b, s.ofType, n)
		}
		return simpleNthChildMatch(s.b, s.ofType, n)
	}
	return nthChildMatch(s.a, s.b, s.last, s.ofType, n)
