package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

func convertToJSON(r io.Reader, w io.Writer, opts options) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return fmt.Errorf("error while reading content: %w", err)
	}
	prefix := data
	if len(prefix) > 10 {
		prefix = prefix[:10]
	}

	var result interface{}
	switch detectContentType(prefix) {
	case contentJson:
		var v interface{}
		if err := json.NewDecoder(bytes.NewReader(data)).Decode(&v); err != nil {
			return fmt.Errorf("error while parsing JSON: %w", err)
		}
		result = v
	case contentXml, contentHtml:
		doc, err := parseXMLDocument(bytes.NewReader(data), true)
		if err != nil {
			return fmt.Errorf("error while parsing XML: %w", err)
		}
		result = documentToJSON(doc, opts.depth)
	default:
		result = map[string]interface{}{"text": string(data)}
	}

	out, err := json.Marshal(result)
	if err != nil {
		return err
	}
	indent := "  "
	if opts.compact {
		indent = ""
	}
	return formatJSON(bytes.NewReader(out), w, indent, opts.colors)
}

func documentToJSON(doc *Node, depth int) map[string]interface{} {
	result := make(map[string]interface{})
	var texts []string
	if s := doc.NextSibling; s != nil && s.Type == TextNode {
		if t := strings.TrimSpace(s.Data); t != "" {
			texts = append(texts, t)
		}
	}
	for c := doc.FirstChild; c != nil; c = c.NextSibling {
		switch c.Type {
		case ElementNode:
			result[c.Data] = nodeToJSON(c, depth)
		case TextNode, CharDataNode:
			if t := strings.TrimSpace(c.Data); t != "" {
				texts = append(texts, t)
			}
		}
	}
	if len(texts) > 0 {
		result["#text"] = strings.Join(texts, "\n")
	}
	return result
}

func nodeToJSON(n *Node, depth int) interface{} {
	if depth == 0 {
		return nodeTextForJSON(n)
	}
	obj := make(map[string]interface{})
	for _, a := range n.Attr {
		obj["@"+a.Name.Local] = a.Value
	}
	var texts []string
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		switch c.Type {
		case ElementNode:
			v := nodeToJSON(c, depth-1)
			if existing, ok := obj[c.Data]; ok {
				if arr, ok := existing.([]interface{}); ok {
					obj[c.Data] = append(arr, v)
				} else {
					obj[c.Data] = []interface{}{existing, v}
				}
			} else {
				obj[c.Data] = v
			}
		case TextNode, CharDataNode:
			if t := strings.TrimSpace(c.Data); t != "" {
				texts = append(texts, t)
			}
		}
	}
	if len(texts) > 0 {
		text := strings.Join(texts, "\n")
		if len(obj) == 0 {
			return text
		}
		obj["#text"] = text
	}
	return obj
}

func nodeTextForJSON(n *Node) string {
	var parts []string
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		switch c.Type {
		case TextNode, CharDataNode:
			if t := strings.TrimSpace(c.Data); t != "" {
				parts = append(parts, t)
			}
		case ElementNode:
			parts = append(parts, nodeTextForJSON(c))
		}
	}
	return strings.Join(parts, "\n")
}
